/bin/bash -lc "python3 - <<'PY'
import urllib.request, urllib.parse, json
for q in ['chr1:161530617','1:161530617','chr6:32067917','6:32067917']:
    url='https://www.ebi.ac.uk/gwas/rest/api/singleNucleotidePolymorphisms/search/findByChromosomeNameAndChromosomePosition?chromosomeName='+urllib.parse.quote(q.split(':')[0].replace('chr',''))+'&chromosomePosition='+urllib.parse.quote(q.split(':')[1])
    print('URL',url)
    try:
        print(urllib.request.urlopen(url,timeout=20).read()[:1000])
    except Exception as e: print('ERR',e)
PY"

/bin/bash -lc "python3 - <<'PY'
import urllib.request,json,urllib.parse
for gene in ['FCAR','TNFSF13B','TNFRSF13B','TNFSF13','TRAF3','FCRL3','FCGR2A','FUT2','HGFAC','CD28','REL','LYN','ANXA3','IRF8']:
    url='https://rest.ensembl.org/lookup/symbol/homo_sapiens/'+gene+'?content-type=application/json'
    try:
        data=json.loads(urllib.request.urlopen(url,timeout=10).read())
        print(gene,data.get('seq_region_name'),data.get('start'),data.get('end'))
    except Exception as e: print(gene,'ERR',e)
PY"
